---@class FreePhysicalPowerSubsystem
FreePhysicalPowerSubsystem = class("FreePhysicalPowerSubsystem")

function FreePhysicalPowerSubsystem:initialize( ... )
    NetResponseEventManager:Get():AddListener(MsgID.GET_POWER_S2C_RET , self, self.RecvMsg_GetPhysicalPower)
end

---@param pwrseq number 序号
---@param type number  正常领取0   补领1
function FreePhysicalPowerSubsystem:SendMsg_GetPhysicalPower(pwrseq,type)
    local reqData=CommonHelper:GetNetSendData({PlayerDataManager:Get():GetPlayerRID(),pwrseq,type})
    NetManager:Get():Send(MsgID.GET_POWER_C2S_REQ,reqData)
end

function FreePhysicalPowerSubsystem:RecvMsg_GetPhysicalPower(data)
    ---@type SC_UserPowerGift
    local msg = assert(Dll_PB.decode("UserPowerGift", data))
    log(ProtoMsgHelp.block(msg))
    PlayerDataManager:Get():SetFreePhysicalPower(msg.pwrseq+1,1)
    if msg.myConsume then
        KnapsackDataManager:Get():UpdatePropByConsume(msg.myConsume)
    end
    PlayerDataManager:Get():SetPlayerStaminaAndStaminaTime(msg.stamina, msg.staminatime)
    if UIManager:Get():IsPopViewShow("StaminaView") then
        UINotify:Get():SendNotification(UINotifyEvent.StaminaView_UpdateData, false)
    end
    CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.FreePhysicalPowerTip))

    --UINotify:Get():SendNotification(UINotifyEvent.FreePhysicalPowerRefresh)

    --UINotify:Get():SendNotification(UINotifyEvent.WelfareVideoOpenPage, WelfareFuncType.physical)

    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideo_PageRunAction, { WelfareFuncType.physical, "RefreshView" })
    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideoRefreshBtn )

end

local __subsystem=FreePhysicalPowerSubsystem()
function FreePhysicalPowerSubsystem:Get() return __subsystem end
return __subsystem